CREATE   FUNCTION dbo.fn_GetCustomerTotal(@CustomerID INT)
RETURNS DECIMAL(18,2)
AS
BEGIN
    DECLARE @Total DECIMAL(18,2);
    SELECT @Total = ISNULL(SUM(TotalAmount), 0)
    FROM dbo.Orders
    WHERE CustomerID = @CustomerID;
    RETURN @Total;
END;

