CREATE OR REPLACE FUNCTION dbo.fn_GetCustomerTotal(p_CustomerID INT)
RETURNS DECIMAL(18,2)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_Total DECIMAL(18,2);
BEGIN
    SELECT COALESCE(SUM(TotalAmount), 0)
    INTO v_Total
    FROM dbo.Orders
    WHERE CustomerID = p_CustomerID;

    RETURN v_Total;
END;
$$;
